begin;
select set_config('request.jwt.claim.sub','2d50291d-03e3-46a3-b3d8-c4550bc1bce7',true);
do $test$
declare prefix text:='TEST-LOSS-'||substr(gen_random_uuid()::text,1,8);office text;mandor text;work uuid;parent uuid;a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();tool uuid:=gen_random_uuid();warehouse_actor uuid:=gen_random_uuid();other_actor uuid:=gen_random_uuid();req uuid;key uuid:=gen_random_uuid();payload jsonb;bad jsonb;failed boolean;n bigint;recon uuid;today date:=(now() at time zone 'Asia/Jakarta')::date;
begin
 select id_kantor,id_mandor into office,mandor from public.master_mandor where status_aktif limit 1;
 work:=public.create_fasum_spk_atomic(prefix,today,today+30,office,mandor,'[{"nama_pekerjaan":"TEST","bobot":1}]');
 select id_item into parent from public.spk_work_item where id_spk=work;
 perform public.configure_spk_work_atomic(work,'KATEGORI',0,jsonb_build_array(jsonb_build_object('id_kategori',parent,'bobot',1)),'[]');
 perform public.activate_spk_atomic(work);
 insert into public.master_material(id_material,nama_material,kategori,satuan,jenis_item) values(a,prefix||' A','TEST','m','BAHAN'),(b,prefix||' B','TEST','kg','BAHAN'),(tool,prefix||' Tool','TEST','bh','ALAT_PAKAI_ULANG');
 insert into public.material_stock_spk(id_spk,id_material,jumlah,harga_rata_rata) values(work,a,10,100),(work,b,10,200),(work,tool,2,500);
 insert into auth.users(id,email) values(warehouse_actor,prefix||'-warehouse@example.invalid'),(other_actor,prefix||'-marketing@example.invalid');
 insert into public.user_profiles(user_id,role,status_aktif,nama) values(warehouse_actor,'GUDANG',true,prefix),(other_actor,'MARKETING',true,prefix) on conflict(user_id) do update set role=excluded.role,status_aktif=true;
 payload:=jsonb_build_array(jsonb_build_object('id_material',a,'jumlah',2,'tindakan','HILANG_RUSAK','alasan','Test loss'),jsonb_build_object('id_material',b,'jumlah',3,'tindakan','HILANG_RUSAK','alasan','Test damage'),jsonb_build_object('id_material',tool,'jumlah',1,'tindakan','HILANG_RUSAK','alasan','Test tool'));
 select count(*) into n from public.material_transaction;
 perform set_config('request.jwt.claim.sub',warehouse_actor::text,true);execute 'set local role authenticated';
 req:=public.submit_material_loss_atomic(key,work,today-2,payload,'Test');
 if public.submit_material_loss_atomic(key,work,today-2,payload,'Test')<>req or (select count(*) from public.material_loss_approval where request_key=key)<>1 then raise exception 'Idempotent submission failed';end if;
 if (select count(*) from public.material_transaction)<>n or (select jumlah from public.material_stock_spk where id_spk=work and id_material=a)<>10 then raise exception 'Submission changed ledger/stock';end if;
 if (select sum((value->>'biaya')::numeric) from public.material_loss_approval cross join lateral jsonb_array_elements(items) where id_pengajuan=req)<>800 then raise exception 'Cost snapshot/tool double charge';end if;
 failed:=false;begin perform public.decide_material_loss_atomic(req,'SETUJUI','Test');exception when others then if sqlerrm like '%DIREKTUR%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Warehouse approved own request';end if;
 failed:=false;begin perform public.post_spk_material_reconciliation_atomic(work,payload);exception when others then if sqlerrm like '%DISETUJUI DIREKTUR%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Legacy bypass';end if;
 perform set_config('kavio.material_loss_apply',req::text,true);
 failed:=false;begin perform public.post_material_document_dated_atomic('RECONCILE',today,jsonb_build_object('p_id_spk',work,'p_items',payload));exception when others then if sqlerrm like '%DISETUJUI DIREKTUR%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Forged setting bypass';end if;
 perform set_config('request.jwt.claim.sub',other_actor::text,true);
 if exists(select 1 from public.material_loss_approval where id_pengajuan=req) then raise exception 'Unauthorized proposal read';end if;
 failed:=false;begin perform public.submit_material_loss_atomic(gen_random_uuid(),work,today,payload);exception when others then if sqlerrm like '%FORBIDDEN%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Marketing submitted loss';end if;
 perform set_config('request.jwt.claim.sub','2d50291d-03e3-46a3-b3d8-c4550bc1bce7',true);
 -- Director cannot forge the pending request into the posting engine either.
 failed:=false;begin perform public.post_spk_material_reconciliation_atomic(work,payload);exception when others then if sqlerrm like '%DISETUJUI DIREKTUR%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Director forged setting bypass';end if;
 perform public.decide_material_loss_atomic(req,'SETUJUI','Verified');
 select id_rekonsiliasi into recon from public.material_loss_approval where id_pengajuan=req and status='DISETUJUI';
 if recon is null or (select count(*) from public.material_transaction where id_rekonsiliasi=recon)<>3 or (select sum(biaya_dibebankan) from public.material_transaction_item join public.material_transaction using(id_transaksi) where id_rekonsiliasi=recon)<>800 or (select jumlah from public.material_stock_spk where id_spk=work and id_material=a)<>8 then raise exception 'Approval did not post once';end if;
 if exists(select 1 from public.material_transaction where id_rekonsiliasi=recon and tanggal<>today-2) or not exists(select 1 from public.material_spk_reconciliation where id_rekonsiliasi=recon and diajukan_oleh=warehouse_actor and diselesaikan_oleh=auth.uid()) then raise exception 'Business date/actors lost';end if;
 if (select jumlah_hilang_rusak from public.v_spk_material_actual where id_spk=work and id_material=a)<>2 then raise exception 'Actual RAB loss missing';end if;
 failed:=false;begin perform public.decide_material_loss_atomic(req,'SETUJUI');exception when others then if sqlerrm like '%SUDAH DIPROSES%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Approval posted twice';end if;
 req:=public.submit_material_loss_atomic(gen_random_uuid(),work,today,payload);
 perform public.decide_material_loss_atomic(req,'TOLAK','Not justified');
 req:=public.submit_material_loss_atomic(gen_random_uuid(),work,today,payload);
 perform public.decide_material_loss_atomic(req,'BATAL','Recheck');
 if (select diputuskan_oleh from public.material_loss_approval where id_pengajuan=req) is distinct from auth.uid() then raise exception 'Cancellation actor missing';end if;
 if (select jumlah from public.material_stock_spk where id_spk=work and id_material=a)<>8 or (select count(*) from public.material_transaction)<>n+3 then raise exception 'Reject/cancel changed stock';end if;
 req:=public.submit_material_loss_atomic(gen_random_uuid(),work,today,payload);
 execute 'reset role';update public.material_stock_spk set harga_rata_rata=110 where id_spk=work and id_material=a;execute 'set local role authenticated';
 failed:=false;begin perform public.decide_material_loss_atomic(req,'SETUJUI');exception when others then if sqlerrm like '%HARGA BERUBAH%' then failed:=true;else raise;end if;end;if not failed or (select status from public.material_loss_approval where id_pengajuan=req)<>'DIAJUKAN' or (select count(*) from public.material_transaction)<>n+3 then raise exception 'Stale price posted/non-atomic';end if;
 perform public.decide_material_loss_atomic(req,'BATAL','Price changed');
 bad:=jsonb_set(payload,'{0,jumlah}','99');
 failed:=false;begin perform public.submit_material_loss_atomic(gen_random_uuid(),work,today,bad);exception when others then if sqlerrm like '%SISA STOK%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Overstock loss accepted';end if;
 bad:=jsonb_set(payload,'{0,jumlah}','"NaN"');
 failed:=false;begin perform public.submit_material_loss_atomic(gen_random_uuid(),work,today,bad);exception when others then if sqlerrm like '%TIDAK VALID%' then failed:=true;else raise;end if;end;if not failed then raise exception 'NaN loss accepted';end if;
 bad:=payload||jsonb_build_array(payload->0);
 failed:=false;begin perform public.submit_material_loss_atomic(gen_random_uuid(),work,today,bad);exception when others then if sqlerrm like '%DUPLIKAT%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Duplicate loss accepted';end if;
 failed:=false;begin perform public.submit_material_loss_atomic(gen_random_uuid(),work,today+1,payload);exception when others then if sqlerrm like '%MASA DEPAN%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Future loss accepted';end if;
 if has_table_privilege('authenticated','public.material_loss_approval','update') or has_function_privilege('authenticated','public.kavio_material_loss_apply_allowed(uuid,jsonb)','execute') or has_function_privilege('anon','public.decide_material_loss_atomic(uuid,text,text)','execute') then raise exception 'Direct mutation/internal/anon privilege';end if;
 execute 'reset role';
end $test$;
rollback;
select 'PASS: multibarang, no stock reservation, Director-only, RLS, forged setting, legacy bypass, idempotency, atomic approval, tool single charge, historical date, RAB, rejection/cancellation, stale valuation and invalid quantities' verification;
